  ('Y''a des légumes au balcon !', 'Mark Ridsdill Smith', 'Maison', null, null, '9782360987887', 'Terre vivante', '2023', 287, 'fre', 'Livre broché', 'DL 2023', '52-Langres', '635.967 1', 'Broché', '25 cm', 'ill. en coul.', 'Conseils d''expert', 'Cultures sur balcon', 'Laurence Seguin', null, '635.9 RID'),
  ('Un sol vivant', 'Xavier Mathias', 'Maison', null, null, '9782815310819', '"Rustica" éditions', '2018', 79, 'fre', 'Livre broché', 'DL 2018', '01-Péronnas', '631.58', 'Broché', '21 cm', 'ill. en coul.', null, 'Permaculture ; Écologie des sols', null, null, '631.5 MAT'),
  ('Triste tigre', 'Neige Sinno', 'Autres', '« J ai voulu y croire, j ai voulu rêver que le royaume de la littérature m accueillerait comme n importe lequel des orphelins qui y trouvent refuge, mais même à travers l art, on ne peut pas sortir vainqueur de l abjection. La littérature ne m a pas sauvée. Je ne suis pas sauvée. »', null, '9782073115799', 'Gallimard', '2025', 275, 'fre', 'Livre de poche', 'DL 2025', 'impr. en Espagne', '362.760 92', 'Broché', '18 cm', 'ill.', 'Collection Folio, 7546', 'Abus sexuels à l''égard des enfants -- France -- 1990-2020', null, null, '362.7 SIN'),
  ('Le lambeau', 'Philippe Lançon', 'Autres', null, null, '9782072873706', 'Gallimard', '2019', 509, 'fre', 'Livre de poche', 'DL 2019', '45-Malesherbes', '362.889 3170944', 'Broché', '18 cm', null, 'Collection Folio, 6738', 'Attentats contre Charlie hebdo et l''Hyper Cacher (Paris, France ; 2015)', null, null, '362.8 LAN'),
  ('Vivre avec nos morts', 'Delphine Horvilleur', 'Autres', 'Un rabbin est confronté chaque jour au mystère de la mort. Pour accompagner les mourants et réconforter les endeuillés, il tente de transmuer l''inéluctable, d''y trouver du sens : « Je me tiens aux côtés de femmes et d''hommes qui, aux moments charnières de leurs vies, ont besoin de récits », écrit Delphine Horvilleur. Ce livre de consolation tresse étroitement trois fils – le conte, l''exégèse et la confession : la narration d''une existence interrompue, la manière de donner une signification à cette mort à travers les textes de la tradition, et l''évocation d''une blessure intime ou la remémoration d''un souvenir enfoui. Les textes sacrés ouvrent un passage entre les vivants et les défunts, et « le rôle d''un conteur est de se tenir à la porte pour s''assurer qu''elle reste ouverte », nous invitant ainsi à faire la paix avec nos disparus et avec notre propre histoire.Un essai lumineux et intime. Libération.Une réflexion éblouissante. L''Obs.Un puissant hymne à la vie. Le Monde.PRIX BABELIO NON-FICTION 2021.', null, '9782253104827', 'le Livre de poche', '2022', 206, 'fre', 'Livre de poche', 'DL 2022', '72-La Flèche', '296.33', 'Broché', '18 cm', null, 'Le livre de poche, 36661', 'Mort (religion) -- Judaïsme', null, null, '296.3 HOR'),
  ('Une éducation', 'Tara Westover', 'Autres', 'Enfant, Tara Westover n''a jamais fréquenté l''école, ni vu de médecins, ni même été déclarée à l''administration parce que son père, mormon, ne croyait ni en la Médecine officielle ni en l''école publique, orchestrée par le diable. Il attendait la Fin des temps. Alors que son père s''enferme dans ses convictions survivalistes et radicales et qu''un de ses frères cède à la violence, Tara décide à seize ans de prendre son destin en main et de s''éduquer toute seule. Sa détermination l''éloignera de ceux qu''elle aime et l''emmènera au-delà des océans, d''Harvard à Cambridge sans qu''elle ne cesse de s''interroger. Quel est le prix à payer quand la loyauté envers sa famille entre en conflit avec la loyauté envers soi-même ?Une éducation est le récit d''une construction de soi et d''une rupture douloureuse. Forte de la lucidité propre aux grands auteurs, Tara Westover nous raconte comment elle est devenue adulte grâce à une éducation qui lui a appris à penser, à douter, tout en restant fidèle à elle-même.Une histoire à la fois étouffante et lumineuse qui prouve qu''il est possible de se réinventer. America.Un extraordinaire récit. Madame Figaro.Traduit de l''anglais (États-Unis) par Johan Frederik Hel Guedj.', null, '9782253820369', 'le Livre de poche', '2020', 568, 'fre', 'Livre de poche', 'DL 2020', '72-La Flèche', '289.373 092', 'Broché', '18 cm', null, 'Le livre de poche, 35926', 'Fondamentalisme mormon -- Idaho (États-Unis) -- 1990-2020', 'Johan Frederick Hel Guedj', null, '289.3 WES'),
  ('Devenir', 'Michelle Obama', 'Autres', 'Michelle Obama s''est imposée, au cours d''un parcours exemplaire, comme l''une des figures les plus remarquables de notre époque. Comme Première dame des États-Unis – et la première Afro-américaine à occuper cette fonction – elle a contribué à ouvrir la Maison-Blanche au plus grand nombre de manière chaleureuse et accueillante, et n''a pas ménagé ses efforts pour défendre les droits des femmes et des filles aux États-Unis comme dans le monde  ; elle est parvenue à changer les mentalités pour que les familles puissent mener des vies actives et plus saines, tout en soutenant son mari alors qu''il dirigeait l''Amérique pendant des moments difficiles. Le tout, sans oublier à l''occasion de faire la démonstration de ses talents de danseuse et de chanteuse, ni surtout d''élever deux jeunes filles en les aidant à garder les pieds sur terre sous le regard implacable des médias du monde entier.Dans ses mémoires, un récit passionnant et marqué par une puissante introspection, Michelle Obama invite les lecteurs dans son univers, à travers la chronique des expériences qui ont fait d''elle la femme qu''elle est aujourd''hui, depuis son enfance dans le South Side de Chicago en passant par les années où elle a dû concilier sa vie d''avocate et de mère de famille, jusqu''aux deux mandats passés à la Maison-Blanche. Avec la sincérité, l''humour et l''esprit qu''on lui connaît, elle décrit ses victoires comme ses défaites, publiques et privées, et raconte toute son histoire telle qu''elle l''a vécue. Devenir retrace le parcours intime d''une femme de caractère qui a toujours su aller au-delà de ce qu''on attendait d''elle – une histoire qui nous encourage à faire de même.', null, '9782213706115', 'Fayard', '2018', 494, 'fre', 'Livre broché', 'DL 2018', '72-La Flèche', '320.973 092', 'Broché', '24 cm', 'ill. en coul.', null, null, 'l''anglais (États-Unis) par Odile Demange et Isabelle Taudière', null, '320.9 OBA'),
  ('Combats et métamorphoses d''une femme', 'Édouard Louis', 'Autres', null, 'https://covers.openlibrary.org/b/isbn/9782021312546-L.jpg', '9782021312546', 'Éditions du Seuil', '2021', 116, 'fre', 'Livre broché', 'DL 2021', '61-Lonrai', null, 'Broché', '19 cm', 'ill.', null, null, null, null, 'DOC LOU'),
  ('Le consentement', 'Vanessa Springora', 'Autres', 'Au milieu des années 80, élevée par une mère divorcée, V. comble par la lecture le vide laissé par un père aux abonnés absents. À treize ans, dans un dîner, elle rencontre G., un écrivain dont elle ignore la réputation sulfureuse. Dès le premier regard, elle est happée par le charisme de cet homme de cinquante ans aux faux airs de bonze, par ses œillades énamourées et l''attention qu''il lui porte. Plus tard, elle reçoit une lettre où il lui déclare son besoin «  impérieux  » de la revoir. Omniprésent, passionné, G. parvient à la rassurer : il l''aime et ne lui fera aucun mal. Alors qu''elle vient d''avoir quatorze ans, V. s''offre à lui corps et âme. Les menaces de la brigade des mineurs renforcent cette idylle dangereusement romanesque. Mais la désillusion est terrible quand V. comprend que G. collectionne depuis toujours les amours avec des adolescentes, et pratique le tourisme sexuel dans des pays où les mineurs sont vulnérables. Derrière les apparences flatteuses de l''homme de lettres, se cache un prédateur, couvert par une partie du milieu littéraire. V. tente de s''arracher à l''emprise qu''il exerce sur elle, tandis qu''il s''apprête à raconter leur histoire dans un roman. Après leur rupture, le calvaire continue, car l''écrivain ne cesse de réactiver la souffrance de V. à coup de publications et de harcèlement.«  Depuis tant d''années, mes rêves sont peuplés de meurtres et de vengeance. Jusqu''au jour où la solution se présente enfin, là, sous mes yeux, comme une évidence  : prendre le chasseur à son propre piège, l''enfermer dans un livre  », écrit-elle en préambule de ce récit libérateur.Plus de trente ans après les faits, Vanessa Springora livre ce texte fulgurant, d''une sidérante lucidité, écrit dans une langue remarquable. Elle y dépeint un processus de manipulation psychique implacable et l''ambiguïté effrayante dans laquelle est placée la victime consentante, amoureuse. Mais au-delà de son histoire individuelle, elle questionne aussi les dérives d''une époque, et...', 'https://covers.openlibrary.org/b/isbn/9782246822691-L.jpg', '9782246822691', 'Bernard Grasset', '2020', 205, 'fre', 'Livre broché', 'DL 2020', '72-La Flèche', '362.760 92', 'Broché', '21 cm', null, null, 'Abus sexuels à l''égard des enfants -- France -- 1970-....', null, null, '362.7 SPR'),
  ('Sorcières', 'Mona Chollet', 'Autres', 'Tremblez, les sorcières reviennent ! disait un slogan féministe des années 1970. Image repoussoir, représentation misogyne héritée des procès et des bûchers des grandes chasses de la Renaissance, la sorcière peut pourtant, affirme Mona Chollet, servir pour les femmes d''aujourd''hui de figure d''une puissance positive, affranchie de toutes les dominations. Qu''elles vendent des grimoires sur Etsy, postent des photos de leur autel orné de cristaux sur Instagram ou se rassemblent pour jeter des sorts à Donald Trump, les sorcières sont partout. Davantage encore que leurs aînées des années 1970, les féministes actuelles semblent hantées par cette figure. La sorcière est à la fois la victime absolue, celle pour qui on réclame justice, et la rebelle obstinée, insaisissable. Mais qui étaient au juste celles qui, dans l''Europe de la Renaissance, ont été accusées de sorcellerie ? Quels types de femme ces siècles de terreur ont-ils censurés, éliminés, réprimés ? Ce livre en explore trois et examine ce qu''il en reste aujourd''hui, dans nos préjugés et nos représentations : la femme indépendante –; puisque les veuves et les célibataires furent particulièrement visées ; la femme sans enfant –; puisque l''époque des chasses a marqué la fin de la tolérance pour celles qui prétendaient contrôler leur fécondité ; et la femme âgée – devenue, et restée depuis, un objet d''horreur. Enfin, il sera aussi question de la vision du monde que la traque des sorcières a servi à promouvoir, du rapport guerrier qui s''est développé alors tant à l''égard des femmes que de la nature : une double malédiction qui reste à lever.', 'https://covers.openlibrary.org/b/isbn/9782355221224-L.jpg', '9782355221224', 'Zones', '2018', 231, 'fre', 'Livre broché', 'DL 2018', '61-Lonrai', '305.42', 'Broché', '21 cm', null, null, 'Femmes -- Conditions sociales -- Histoire ; Femmes -- Dans les représentations sociales -- Histoire', null, null, '305.4 CHO'),
  ('La familia grande', 'Camille Kouchner', 'Autres', null, 'https://covers.openlibrary.org/b/isbn/9782021472660-L.jpg', '9782021472660', 'Éditions du Seuil', '2021', 203, 'fre', 'Livre broché', 'DL 2021', '53-Mayenne', '306.877 092', 'Broché', '21 cm', null, null, 'Enfants victimes d''abus sexuels devenus adultes', null, null, '306.8 KOU'),
  ('Une terre promise', 'Barack Obama', 'Autres', null, 'https://covers.openlibrary.org/b/isbn/9782213706122-L.jpg', '9782213706122', 'Fayard', '2020', 840, 'fre', 'Livre broché', 'DL 2020', '18-Saint-Amand-Montrond', '320.973 092', 'Broché', '25 cm', 'ill. en coul.', null, null, 'l''anglais (États-Unis) par Pierre Demarty, Charles Recoursé et Nicolas Richard', null, '320.9 OBA'),
  ('Moi, Tituba sorcière noire de Salem', 'Maryse Condé', 'Fonds local', null, 'https://covers.openlibrary.org/b/isbn/9782070379293-L.jpg', '9782070379293', 'Gallimard', '1988', 277, 'fre', 'Livre de poche', '1988', 'Impr. Bussière', '843', 'Broché', '18 cm', 'couv. ill. en coul.', 'Collection Folio, 1929', null, null, null, 'FL CON'),
  ('La Rue Cases-Nègres', 'Joseph Zobel', 'Fonds local', 'Le narrateur est José, un enfant noir vivant dans les champs de canne à sucre. Il vit à Petit-Morne (un bourg de Rivière-Salée) et, plus précisément, dans la rue Cases-Nègres, voie principale de l''ancien quartier des esclaves. José est élevé par sa grand-mère, qu''il surnomme M''man Tine. Sa mère est partie travailler en ville à Fort-de-France. José, avec tous les petits enfants du bourg, quand ils ne travaillent pas encore aux champs, passe ses journées à traîner dans la rue à s''amuser. M''man Tine travaille elle aussi dans les champs. Les enfants ayant fait une grosse bêtise, les parents décident de les emmener travailler aux champs avec eux. M''man Tine refuse de faire trimer son petit-fils dans les plantations et nourrit l''espoir qu''il sorte de cette vie en allant à l''école. Elle l''inscrit donc à l''école située dans le bourg voisin, nommé Petit-Bourg. L''école joue un rôle prépondérant dans cette société encore largement coloniale. José devient bon élève à l’école si bien que son professeur l’encourage à entrer au lycée à Fort-de-France. Il réussit le concours et doit envisager la vie en ville. Sa mère le recueille et doit changer de travail pour vivre avec lui. (Source : Wikipédia)', 'https://covers.openlibrary.org/b/isbn/9782708704336-L.jpg', '9782708704336', 'Présence africaine', '1984', 311, 'fre', 'Livre broché', '1984', 'Impr. Bussière', null, 'Broché', '18 cm', 'couv. ill. en coul.', null, null, null, null, 'FL ZOB'),
  ('Le coeur à rire et à pleurer', 'Maryse Condé', 'Fonds local', null, 'https://covers.openlibrary.org/b/isbn/9782266098687-L.jpg', '9782266098687', 'Pocket', '2001', 154, 'fre', 'Livre de poche', '2001', 'Bussière Camedan impr.', '972.976', 'Broché', '18 cm', 'couv. ill. en coul.', 'Pocket, 10883', 'Moeurs et coutumes -- Guadeloupe -- 1945-1970', null, null, 'FL 972.9 CON'),
  ('La grande drive des esprits', 'Gisèle Pineau', 'Fonds local', 'Léonce, jeune homme plein de qualités et travailleur, traîne une infirmité de naissance, un pied-bot qui éloigne de lui les femmes. Sa persévérance et ses mots d''amour passionnés finissent cependant par séduire la belle Myrtha. Ils se marient, ont des enfants, leurs affaires prospèrent. Tout aurait pu se poursuivre sans encombre... Mais les rumeurs et les malédictions de toutes sortes s''abattent sur la famille, de génération en génération. Gisèle Pineau brosse le portrait d''une famille, dans les mornes de Guadeloupe, où la drive, ou errance, des esprits – esprits vengeurs des ancêtres, esprits retors – pèse sur le destin des hommes.', 'https://covers.openlibrary.org/b/isbn/9782848765914-L.jpg', '9782848765914', 'Philippe Rey', '2017', 221, 'fre', 'Livre broché', 'DL 2017', 'Normandie roto impr.', null, 'Broché', '19 cm', null, 'Fugues', null, null, null, 'FL PIN')
),
new_books as (
  insert into public.books (title, author, category, summary, cover_url, isbn, publisher, published_date, page_count, language, format, legal_deposit, printer, dewey, binding, dimensions, illustrations, collection, subjects, translator, illustrator, shelf_location, cover_initial, available, equipped, on_site_only, commune_id)
  select s.*, upper(left(s.title, 1)), true, true, false, 1
  from src s
  where not exists (select 1 from public.books b where b.commune_id = 1 and b.isbn = s.isbn)
  returning id, shelf_location
)
insert into public.book_copies (book_id, barcode, owner_commune_id, current_commune_id, shelf_location, status, source, acquired_at)
select id, 'BLIGO-' || lpad(id::text, 6, '0'), 1, 1, shelf_location, 'available', 'purchase', current_date
from new_books;

-- Vérification : nombre de documents par catégorie à Val-Fleuri
select category, count(*) from public.books where commune_id = 1 and not coalesce(archived, false) group by category order by category;
